//! AAO public first-page PPP catalog to source-linked PDF; ASP.NET pagination is unverified.
use super::{common,Adapter,PlanRow};
use crate::guidelines::doc::{GuidelineDoc,Rights};
use crate::guidelines::fetch::{Fetched,Fetcher};
use crate::guidelines::html::{sel,text_of};
use crate::guidelines::registry::SourceEntry;
use anyhow::{bail,Context,Result};
use scraper::Html;
use serde_json::json;
use std::collections::HashSet;
use url::Url;
pub struct AaoOphthalmology;
fn catalog(html:&str,base:&Url)->Result<Vec<(String,String,String)>>{
 let d=Html::parse_document(html);let mut rows=Vec::new();let mut seen=HashSet::new();
 for card in d.select(&sel(".list-item.cms_content")){let Some(a)=card.select(&sel(".title a[href]")).next() else {continue};let Some(url)=common::link(base,a.value().attr("href").unwrap_or_default())else{continue};let u=Url::parse(&url)?;if u.origin()!=base.origin()||!matches!(u.path().split('/').nth(2),Some("preferred-practice-pattern"|"summary-benchmark-detail")){continue;}let title=text_of(&a);let date=card.select(&sel("[itemprop=datePublished]")).next().map(|e|text_of(&e)).unwrap_or_default();if !title.is_empty()&&seen.insert(url.clone()){rows.push((url,title,date));}}
 if rows.is_empty(){bail!("AAO first catalog page has no recognised cards")}Ok(rows)
}
fn detail(html:&str,base:&Url)->Result<(Vec<String>,Option<String>)>{let d=Html::parse_document(html);let mut out=vec![];let mut seen=HashSet::new();for a in d.select(&sel("a[id$='PdfHyperlink'][href]")){let Some(u)=common::link(base,a.value().attr("href").unwrap_or_default())else{continue};let p=Url::parse(&u)?;if p.origin()==base.origin()&&p.path().starts_with("/Assets/")&&seen.insert(u.clone()){out.push(u)}}if out.is_empty(){bail!("AAO source detail has no PDF Version link")}let notice=d.select(&sel("meta[name=legal_notice][content]")).next().and_then(|e|e.value().attr("content")).map(String::from);Ok((out,notice))}
fn complete(f:&Fetched)->bool{f.is_pdf()&&f.body.iter().rev().take(2048).copied().collect::<Vec<_>>().windows(5).any(|x|x==b"FOE%%")}
fn unresolved(src:&SourceEntry,url:String,e:String)->PlanRow{PlanRow{source_id:src.id.clone(),doc_key:format!("{}-unresolved",common::short_hash(&url)),url,title:None,rendition:None,version:None,extra:json!({"discovery_error":e})}}
#[async_trait::async_trait]impl Adapter for AaoOphthalmology{
 async fn discover(&self,src:&SourceEntry,f:&Fetcher,limit:Option<usize>)->Result<Vec<PlanRow>>{if limit==Some(0){return Ok(vec![])}let cat=f.get_ok(src.catalog_url.as_deref().context("AAO catalog missing")?).await?;let b=Url::parse(&cat.record.final_url)?;let mut rows=vec![];let mut errors=vec![];for(topic,title,date)in catalog(&cat.text(),&b)?{let p=match f.get_ok(&topic).await{Ok(x)=>x,Err(e)=>{errors.push(unresolved(src,topic,format!("{e:#}")));continue}};let base=Url::parse(&p.record.final_url)?;if base.origin()!=b.origin(){errors.push(unresolved(src,topic,"source topic origin changed".into()));continue;}let(links,_)=match detail(&p.text(),&base){Ok(x)=>x,Err(e)=>{errors.push(unresolved(src,topic,format!("{e:#}")));continue}};for pdf in links{let x=match f.get_ok(&pdf).await{Ok(x)if complete(&x)=>x,Ok(_)=>{errors.push(unresolved(src,pdf,"PDF incomplete".into()));continue},Err(e)=>{errors.push(unresolved(src,pdf,format!("{e:#}")));continue}};let key=common::short_hash(&pdf);rows.push(PlanRow{source_id:src.id.clone(),doc_key:format!("{key}-{}",&x.record.sha256[..12]),url:pdf,title:Some(title.clone()),rendition:Some("pdf".into()),version:None,extra:json!({"work_key":key,"topic_url":topic,"topic_sha256":p.record.sha256,"pdf_sha256":x.record.sha256,"catalog_date":date,"catalog_fetch":cat.record})});if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}}}let n=limit.map(|n|n.saturating_sub(rows.len())).unwrap_or(usize::MAX);rows.extend(errors.into_iter().take(n));Ok(rows)}
 async fn extract(&self,src:&SourceEntry,f:&Fetcher,row:&PlanRow)->Result<GuidelineDoc>{if let Some(e)=row.extra["discovery_error"].as_str(){bail!("AAO source unresolved: {e}")}let topic=row.extra["topic_url"].as_str().context("AAO topic missing")?;let t=f.get_ok(topic).await?;if row.extra["topic_sha256"].as_str().is_some_and(|s|s!=t.record.sha256){bail!("AAO topic changed since discovery")}let(links,notice)=detail(&t.text(),&Url::parse(&t.record.final_url)?)?;if !links.contains(&row.url){bail!("AAO source no longer links PDF")}let pdf=f.get_ok(&row.url).await?;if !complete(&pdf)||row.extra["pdf_sha256"].as_str().is_some_and(|s|s!=pdf.record.sha256){bail!("AAO PDF changed or incomplete")}let(blocks,mut warnings,_)=super::static_list::blocks_for(&pdf,None,0).await?;if blocks.is_empty(){bail!("AAO PDF has no mapped text")}warnings.push("Only the first catalog page is mapped: ASP.NET postback pagination and all 33 observed browser cards are not yet reproduced. PDF tables, figures, grade associations and layout require independent verification.".into());let rights=if let Some(n)=notice{Rights{status:"restricted".into(),note:Some(n),evidence_urls:vec![topic.into()],..Default::default()}}else{warnings.push("AAO source rights notice not observed; rights unknown.".into());Rights{status:"unknown".into(),..Default::default()}};let mut fetches=vec![];if let Ok(r)=serde_json::from_value::<crate::guidelines::doc::FetchRecord>(row.extra["catalog_fetch"].clone()){fetches.push(r)}fetches.push(t.record);fetches.push(pdf.record);Ok(GuidelineDoc{source_id:src.id.clone(),doc_key:row.doc_key.clone(),work_key:row.extra["work_key"].as_str().map(String::from),title:row.title.clone().unwrap_or_default(),url:row.url.clone(),item_type:Some("source_linked_ppp_pdf".into()),status:"unknown".into(),rights,search_metadata:json!({"topic_url":topic,"source_catalog_date":row.extra["catalog_date"]}),blocks,fetches,warnings,..Default::default()})}
}
#[cfg(all(test, feature = "guideline-fixtures"))]mod tests{use super::*;#[test]fn source_catalog_topic_and_pdf_edge_are_genuine(){let html=[include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/aao_ophthalmology/catalog-1.html")),include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/aao_ophthalmology/catalog-2.html"))].concat();let topic=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/aao_ophthalmology/adult-eye-topic.html"));let base=Url::parse("https://www.aao.org/education/guidelines-browse?filter=Preferred+Practice+Patterns&sub=AllPreferredPracticePatterns").unwrap();let rows=catalog(&html,&base).unwrap();assert!(rows.iter().any(|(u,t,d)|u.ends_with("/comprehensive-adult-medical-eye-evaluation-ppp")&&t.contains("2025")&&d.contains("2026")));let u=Url::parse("https://www.aao.org/education/preferred-practice-pattern/comprehensive-adult-medical-eye-evaluation-ppp").unwrap();let(urls,notice)=detail(topic,&u).unwrap();assert!(urls.iter().any(|u|u=="https://www.aao.org/Assets/35e2c761-7283-4c0e-a62a-51f6c9b57627/639069319608200000/comprehensive-adult-medical-eye-eval"));assert!(notice.unwrap().contains("artificial intelligence"));}}
